import React, { useState } from "react";
import { createDelivery } from "../api/deliveryApi";
import { useNavigate } from "react-router-dom";
import styles from "./CreateDeliveryForm.module.css";

export default function CreateDeliveryForm() {
  const navigate = useNavigate();
  const [form, setForm] = useState({
    customerId: "",
    lat: "",
    lng: "",
    status: "Assigned"
  });

  const [assignedDriver, setAssignedDriver] = useState<string | null>(null);
  const [error, setError] = useState("");

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await createDelivery({
        customerId: form.customerId,
        location: {
          lat: parseFloat(form.lat),
          lng: parseFloat(form.lng),
        },
        status: form.status,
      });

      const assigned = res.data?.driverId || "Unknown";
      setAssignedDriver(assigned);
      setError("");
      alert("✅ Delivery created successfully!");
      setForm({ customerId: "", lat: "", lng: "", status: "Assigned" });
    } catch (err) {
      console.error("Error creating delivery:", err);
      setError("❌ Failed to create delivery");
    }
  };

  return (
    <form onSubmit={handleSubmit} className={styles.form}>
      <h2>Create Delivery</h2>

      <input
        className={styles.input}
        type="text"
        name="customerId"
        placeholder="Customer ID"
        value={form.customerId}
        onChange={handleChange}
        required
      />

      <input
        className={styles.input}
        type="text"
        name="lat"
        placeholder="Latitude"
        value={form.lat}
        onChange={handleChange}
        required
      />

      <input
        className={styles.input}
        type="text"
        name="lng"
        placeholder="Longitude"
        value={form.lng}
        onChange={handleChange}
        required
      />

      <select
        className={styles.select}
        name="status"
        value={form.status}
        onChange={handleChange}
      >
        <option value="Assigned">Assigned</option>
        <option value="Pending">Pending</option>
        <option value="In Transit">In Transit</option>
        <option value="Delivered">Delivered</option>
      </select>

      <button type="submit" className={styles.button}>
        Create Delivery
      </button>

      <button type="button" className={styles.backButton} onClick={() => navigate("/")}>
        ← Back to Dashboard
      </button>

      {assignedDriver && (
        <div className={styles.assigned}>
          ✅ Assigned Driver: <strong>{assignedDriver}</strong>
        </div>
      )}

      {error && <p className={styles.error}>{error}</p>}
    </form>
  );
}
